define([], function() {
    /**
     * Moves a table row up or down by swapping it with its sibling row.
     * @param {HTMLTableRowElement} row The row to move.
     * @param {'up' | 'down'} direction The direction to move.
     * @returns {boolean} True if moved; false if no suitable sibling.
     */
    const moveRow = (row, direction) => {
        console.log('DEBUG: moveRow called with direction:', direction);

        if (!row) {
            console.log('DEBUG: No row element provided to moveRow');
            return false;
        }

        const sibling = direction === 'up'
            ? row.previousElementSibling
            : row.nextElementSibling;

        console.log('DEBUG: sibling element found:', sibling);

        if (!sibling || sibling.nodeType !== 1) {
            console.log('DEBUG: No suitable sibling to swap with, or sibling is not an element node');
            return false;
        }

        // Insert the row before/after the sibling
        if (direction === 'up') {
            row.parentNode.insertBefore(row, sibling);
            console.log('DEBUG: Row moved up above sibling');
        } else {
            row.parentNode.insertBefore(sibling, row);
            console.log('DEBUG: Row moved down below sibling');
        }
        return true;
    };

    /**
     * Initializes click handlers for .move-up and .move-down buttons.
     */
    const init = () => {
        console.log('DEBUG: init() called - attaching event listeners for .move-up and .move-down');

        // Attach to all elements with these classes
        document.querySelectorAll('.move-up, .move-down').forEach(button => {
            button.addEventListener('click', async (e) => {
                e.preventDefault();

                // Determine direction (up or down) based on the button’s classes
                const direction = button.classList.contains('move-up') ? 'up' : 'down';
                console.log('DEBUG: Button clicked. direction =', direction, ', button:', button);

                // Convert data-id attribute to int
                const elementid = parseInt(button.dataset.id, 10);
                console.log('DEBUG: elementid from data-id:', elementid);

                if (isNaN(elementid)) {
                    console.error('DEBUG: Invalid element ID:', button.dataset.id);
                    return;
                }

                // Attempt to find the table row containing this button
                const row = button.closest('tr');
                console.log('DEBUG: Closest row found:', row);

                // Visually move the row in the DOM
                const success = moveRow(row, direction);
                if (!success) {
                    console.log('DEBUG: Could not move row - no suitable sibling found or row is missing');
                    return;
                }

                // Get category ID from M.cfg or URL param
                const catid = M.cfg.catid || new URLSearchParams(window.location.search).get('catid');
                console.log('DEBUG: Category ID resolved to:', catid);

                if (!catid) {
                    console.error('DEBUG: Category ID not found - cannot proceed with AJAX request.');
                    return;
                }

                // Build the payload for the server
                const payload = {
                    elementid: elementid,
                    categoryid: parseInt(catid, 10),
                    direction: direction
                };
                console.log('DEBUG: Payload being sent to server:', payload);

                try {
                    // Construct the AJAX endpoint (sortelements.php) using Moodle’s config
                    const ajaxUrl = M.cfg.wwwroot +
                        '/lib/editor/tiny/plugins/styles/ajax/sortelements.php?sesskey=' +
                        encodeURIComponent(M.cfg.sesskey);

                    console.log('DEBUG: AJAX URL:', ajaxUrl);

                    // Perform the fetch request
                    const response = await fetch(ajaxUrl, {
                        method: 'POST',
                        headers: {
                            'Content-Type': 'application/json',
                            'X-Requested-With': 'XMLHttpRequest'
                        },
                        body: JSON.stringify(payload),
                        credentials: 'same-origin'
                    });

                    console.log('DEBUG: AJAX response status:', response.status);

                    if (!response.ok) {
                        const errorText = await response.text();
                        console.error('DEBUG: Server responded with error text:', errorText);

                        let errorMessage = 'Server error: ' + response.status;

                        // Attempt to parse error as JSON
                        try {
                            const errorJson = JSON.parse(errorText);
                            if (errorJson.message) {
                                errorMessage = errorJson.message;
                            }
                        } catch (e) {
                            // Not valid JSON; just use raw text
                            if (errorText) {
                                errorMessage = errorText.substring(0, 100);
                            }
                        }

                        alert('⚠️ ' + errorMessage);
                        throw new Error(`Server responded with ${response.status}: ${errorMessage}`);
                    }

                    // Parse the response text
                    const text = await response.text();
                    console.log('DEBUG: Raw response text:', text);

                    let data;
                    try {
                        data = JSON.parse(text);
                        console.log('DEBUG: Parsed JSON:', data);
                    } catch (e) {
                        console.error('DEBUG: Response was not valid JSON:', text);
                        alert('⚠️ Server returned invalid JSON: ' + e.message);
                        return;
                    }

                    if (data.status !== 'success') {
                        console.error('DEBUG: Server returned a non-success status:', data);
                        alert('⚠️ ' + (data.message || 'Unknown error.'));
                    } else {
                        console.log('DEBUG: Sort operation completed successfully, server data:', data);
                    }

                } catch (err) {
                    console.error('DEBUG: AJAX operation failed:', err);
                    alert('⚠️ Could not reach the server: ' + err.message);
                }
            });
        });
    };

    return { init };
});
